style.css:
@-moz-document domain("www.nicovideo.jp"), domain("live.nicovideo.jp") {
/* niconico Dark. Modern pages (video, ranking, search, comments) resolve from Panda CSS --colors-* tokens, so re-pointing those flips them in one pass. Home and profiles are legacy DOM, handled by class below. */

  :root {
    color-scheme: dark !important;

    /* ---- Base page + elevated surfaces ---- */
    --colors-layer-background: #14181d !important;
    --colors-layer-surface-high-em: #1c2128 !important;
    --colors-layer-surface-high-em-white: #1c2128 !important;
    --colors-layer-surface-high-em-black: #1c2128 !important;
    --colors-layer-surface-medium-em: #1a1f26 !important;
    --colors-layer-surface-medium-em-white: #1a1f26 !important;
    --colors-layer-surface-medium-em-black: #1a1f26 !important;
    --colors-layer-surface-low-em: #262c33 !important;
    --colors-layer-surface-low-em-black: #262c33 !important;
    --colors-layer-surface-lower-em: #2d333b !important;
    --colors-layer-surface-overlay: #000000cc !important;
    --colors-layer-surface-overlay-black: #000000cc !important;
    --colors-layer-content-overlay: #14181dcc !important;

    /* ---- Text on surfaces ---- */
    --colors-text-on-layer-high-em: #e6edf3 !important;
    --colors-text-on-layer-high-em-white: #e6edf3 !important;
    --colors-text-on-layer-high-em-black: #e6edf3 !important;
    --colors-text-on-layer-medium-em: #c4cdd6 !important;
    --colors-text-on-layer-medium-em-inv: #14181dcc !important;
    --colors-text-on-layer-low-em: #8b949e !important;
    /* Hint text must clear 4.5:1 on BOTH the page base and the elevated card, while staying dimmer than low-em. */
    --colors-text-on-layer-lower-em: #828b95 !important;
    --colors-text-on-layer-visited: #a9b4c0 !important;

    /* Disabled family: the site's #666 is only 2.5:1 on our elevated surface. Lift to a grey that still reads DISABLED — clearly dimmer than the #c4cdd6 body text. --colors-service-color-ch is #666 too but is the CHANNEL brand colour, not a disabled state: leave it. */
    --colors-action-text-on-base_disabled: #7d8590 !important;
    --colors-tab-text-on-base-disabled: #7d8590 !important;
    --colors-icon-base-disabled: #7d8590 !important;
    --colors-icon-watch-controller-disabled: #7d8590 !important;

    /* ---- Borders (soften the bright default lines) ---- */
    --colors-border-base: #262c33 !important;
    --colors-border-high-em: #2d333b !important;
    --colors-action-ui-border: #3a424c !important;

    /* ---- Form inputs (search box, fields) ---- */
    --colors-input-form-background: #0d1117 !important;
    --colors-input-form-input-text: #e6edf3 !important;
    --colors-input-form-placeholder: #8b949e !important;

    /* ---- Icons ---- */
    --colors-icon-base: #c4cdd6 !important;
    --colors-icon-primary: #e6edf3 !important;
    --colors-icon-base-white: #c4cdd6 !important;
    --colors-icon-primary-white: #e6edf3 !important;
    --colors-icon-video-description: #8b949e !important;
    --colors-icon-header-search-base: #8b949e !important;
    --colors-icon-watch-controller-base: #ccd3da !important;

    /* ---- Tabs / on-base actions ---- */
    /* The selected tab pill must be brand azure, not an elevated grey: the unselected chips sit on a 10%-white track computing to ~#25292e, so a grey pill stands only 1.14:1 above them. */
    --colors-tab-base-active: #1f4a78 !important;
    --colors-tab-text-on-base: #c4cdd6 !important;
    --colors-tab-object-on-base: #c4cdd6 !important;
    --colors-tab-text-on-base-active: #e6edf3 !important;
    --colors-tab-object-on-base-active: #e6edf3 !important;
    --colors-tab-text-on-base-hover: #e6edf3 !important;
    --colors-tab-object-on-base-hover: #e6edf3 !important;
    --colors-action-text-on-base: #e6edf3 !important;

    /* Monotone scale — the light end maps to dark surfaces; the dark end (#252525 / #000) already reads dark and is kept for the header bar and the video stage. */
    --colors-monotone--l100: #e6edf3 !important;
    --colors-monotone--l95: #1c2128 !important;
    --colors-monotone--l90: #262c33 !important;
    --colors-monotone--l80: #2d333b !important;
    --colors-monotone--l70: #8b949e !important;

    /* ---- Tooltips / snackbars ---- */
    --colors-tooltip-background: #2d333b !important;
    --colors-tooltip-text-on-background: #e6edf3 !important;
    --colors-snackbar-base: #2d333b !important;
    --colors-snackbar-text-on-base: #e6edf3 !important;

    /* ---- Loading skeleton shimmer ---- */
    --colors-layer-skeleton: linear-gradient(to right, #0000, #ffffff0d, #0000) !important;

    /* niconico accent — keep the brand azure, lifted slightly so links/CTAs stay vivid on near-black. */
    --colors-action-primary-azure: #2f86e6 !important;
    --colors-action-primary-azure-hover: #4799eb !important;
    --colors-text-on-layer-accent-azure: #5fb0e6 !important;
    --colors-action-text-on-tertiary-azure: #5fb0e6 !important;
    --colors-action-text-on-tertiary-azure-inv: #5fb0e6 !important;
    --colors-icon-primary-azure: #5fb0e6 !important;
    --colors-layer-surface-accent-azure: #1f4a78 !important;

    /* Ranking medal ramp. Only the silver step needs lifting — the site's #1466b8 is 2.8:1 on our elevated card. Gold and bronze stay verbatim so the ranks are told apart by hue. The legacy video_top rail hardcodes the same value and needs its own arm. */
    --colors-ranking-grade-silver: #3d8ddd !important;

    /* The site's semantic red (ショート "New" flag, live/error markers) fails AA on the elevated card at its own #e61a1a. Keep it unmistakably red. */
    --colors-text-on-layer-accent-lust: #ff5c5c !important;

    /* ~68 tokens resolve differently under prefers-color-scheme. Pin them to the DARK branch, or a light-OS visitor gets the light branch painted onto our dark surfaces. */
    --colors-service-color-nicovideo-logo: #e6edf3 !important;
    --colors-action-primary: #e6edf3 !important;
    --colors-action-primary-hover: #c4cdd6 !important;
    --colors-action-text-on-primary: #14181d !important;
    --colors-action-base: rgba(230, 237, 243, 0.08) !important;
    --colors-action-base-hover: rgba(230, 237, 243, 0.16) !important;
    --colors-tab-base: rgba(230, 237, 243, 0.08) !important;
    --colors-tab-base-hover: rgba(230, 237, 243, 0.16) !important;
    --colors-action-tertiary-hover: rgba(230, 237, 243, 0.1) !important;
    --colors-action-tertiary-azure-hover: rgba(95, 176, 230, 0.16) !important;
    --colors-action-tertiary-premium-hover: rgba(217, 163, 0, 0.16) !important;
    --colors-action-text-on-tertiary: #8b949e !important;
    --colors-icon-spinner-on-layer: rgba(230, 237, 243, 0.4) !important;
    --colors-icon-unlock: #8b949e !important;
    --colors-border-color-command: rgba(230, 237, 243, 0.3) !important;
    /* Nicoru glyph: the "on" stroke is the brand yellow in the site's dark branch, and the "off" disc must stay a dark chip. */
    --colors-icon-nicoru-on-stroke: #fcd842 !important;
    --colors-icon-nicoru-off-background: #2d333b !important;
    /* The rest of the nicoru family flips with the scheme too: pin it to the dark branch, the ON disc taking the same chip as its "off" twin (the two are told apart by the STROKE, as the site's dark branch does). The washes need a nicoru'd comment to render, which a logged-out session cannot produce, so they are unverified against a live element. Left on the LIGHT branch on purpose: the whole `*-inv` family, `--colors-action-room` and `--colors-action-tag-help-hover` — the light value is the one that belongs on a dark surface. */
    --colors-icon-nicoru-on-background: #2d333b !important;
    --colors-service-color-nicoru-yellow-a10: #af952f1a !important;
    --colors-service-color-nicoru-yellow-a20: #af952f33 !important;
    --colors-service-color-nicoru-yellow-a40: #af952f66 !important;
    --colors-service-color-nicoru-yellow-a60: #af952f99 !important;
    --colors-comment-list-nicoru-lv1: #af952f1a !important;
    --colors-comment-list-nicoru-lv2: #af952f33 !important;
    --colors-comment-list-nicoru-lv3: #af952f66 !important;
    --colors-comment-list-nicoru-lv4: #af952f99 !important;

    /* live.nicovideo.jp carries a SECOND design system — a `--colorset-*` scale plus per-component `--mono*` aliases — switched by a `data-color-theme` attribute on <html> that CSS cannot change, so its dark scale is restated here. Both layers are needed: `--colorset-*` feeds components that redeclare the aliases locally, the bare `--mono*`/`--surface-*` layer covers headers and anchors outside those subtrees. */
    --colorset-base-font: #252525 !important;
    --colorset-base-bg: #1a1a1a !important;
    --colorset-surface-primary: #252525 !important;
    --colorset-surface-secondary: #1a1a1a !important;
    --colorset-surface-float: #333333 !important;
    --colorset-mono1: #ffffff !important;
    --colorset-mono2: #f2f2f2 !important;
    --colorset-mono3: #e6e6e6 !important;
    --colorset-mono4: #b3b3b3 !important;
    --colorset-mono5: #666666 !important;
    --colorset-mono6: #4d4d4d !important;
    --colorset-mono7: #252525 !important;
    --colorset-mono8: #1a1a1a !important;
    --rgb-color-colorset-base-font: 37, 37, 37 !important;
    --rgb-color-colorset-base-bg: 26, 26, 26 !important;
    --rgb-color-colorset-surface-primary: 37, 37, 37 !important;
    --rgb-color-colorset-surface-secondary: 26, 26, 26 !important;
    --rgb-color-colorset-surface-float: 51, 51, 51 !important;
    --rgb-color-colorset-mono1: 255, 255, 255 !important;
    --rgb-color-colorset-mono2: 242, 242, 242 !important;
    --rgb-color-colorset-mono3: 230, 230, 230 !important;
    --rgb-color-colorset-mono4: 179, 179, 179 !important;
    --rgb-color-colorset-mono5: 102, 102, 102 !important;
    --rgb-color-colorset-mono6: 77, 77, 77 !important;
    --rgb-color-colorset-mono7: 37, 37, 37 !important;
    --rgb-color-colorset-mono8: 26, 26, 26 !important;
    /* live's chromatic scale flips too, and the light branch never declares these at all — components then fall back to the literal in their own `var(--blue, #056dff)`, pairing a light fill with our pinned dark ink. */
    --colorset-blue: #559cff !important;
    --colorset-red: #f0607c !important;
    --colorset-rookie: #1dbf71 !important;
    --rgb-color-colorset-blue: 85, 156, 255 !important;
    --rgb-color-colorset-red: 240, 96, 124 !important;
    --rgb-color-colorset-rookie: 29, 191, 113 !important;
    --blue: #559cff !important;
    --red: #f0607c !important;
    --rookie: #1dbf71 !important;
    --base-font: #252525 !important;
    --base-bg: #1a1a1a !important;
    --surface-primary: #252525 !important;
    --surface-secondary: #1a1a1a !important;
    --surface-float: #333333 !important;
    --mono1: #ffffff !important;
    --mono2: #f2f2f2 !important;
    --mono3: #e6e6e6 !important;
    --mono4: #b3b3b3 !important;
    --mono5: #666666 !important;
    --mono6: #4d4d4d !important;
    --mono7: #252525 !important;
    --mono8: #1a1a1a !important;
    --rgb-color-base-font: 37, 37, 37 !important;
    --rgb-color-base-bg: 26, 26, 26 !important;
    --rgb-color-surface-primary: 37, 37, 37 !important;
    --rgb-color-surface-secondary: 26, 26, 26 !important;
    --rgb-color-surface-float: 51, 51, 51 !important;
    --rgb-color-mono1: 255, 255, 255 !important;
    --rgb-color-mono2: 242, 242, 242 !important;
    --rgb-color-mono3: 230, 230, 230 !important;
    --rgb-color-mono4: 179, 179, 179 !important;
    --rgb-color-mono5: 102, 102, 102 !important;
    --rgb-color-mono6: 77, 77, 77 !important;
    --rgb-color-mono7: 37, 37, 37 !important;
    --rgb-color-mono8: 26, 26, 26 !important;
  }

  /* Modern (token) pages — a few literal surfaces that bypass the tokens, plus a couple of util classes Panda emits inline. */
  /* Blank ad slots expose a white iframe fill; a real creative paints over them. */
  .Ads, [class*="Ads"], [class^="Ads"],
  iframe[id*="google_ads"], iframe[id^="ads_"], ins.adsbygoogle,
  aside#header-ad, aside#header-ad > div, aside#header-ad .ad-banner,
  aside.ad-banner, aside.ad-banner > div, aside#player-ad-panel > div {
    background-color: #161b21 !important;
    border-color: #262c33 !important;
  }
  /* Each slot's direct child carries its own `border:1px solid #ddd !important` from a `.PcUniTop…AdContainer .Ads > *` rule the container rule cannot reach. Match its specificity and land later to beat it. */
  [class*="AdContainer"] .Ads > *, .Ads > a {
    background-color: #161b21 !important;
    border-color: #262c33 !important;
  }
  /* NOTE (verified, do not "fix"): the white 300x250 / 728x90 block that sometimes appears here is a real creative inside a NESTED cross-origin doubleclick.net frame — unreachable from this document. Darkening real content is worse than a white ad. */

  /* Selected segment-group pill (watch-page settings dialogs). It fills from --colors-text-on-layer-accent-azure, a token whose other role is LINK INK — the light azure that role needs puts the white label at ~2:1. Use the theme's active surface instead. */
  [data-scope="segment-group"][data-part="item"][data-state="checked"] {
    background-color: #1f4a78 !important; color: #e6edf3 !important;
  }

  /* The ad overlay's controls colour their labels through monotone.l95, which we remap dark. The ad creative itself is untouched. */
  #nv_watch_VideoAdContainer button,
  #nv_watch_VideoAdContainer [class*="pos_absolute"] { color: #e6edf3 !important; }

  /* Hardcodes #f2f2f2 / #1a1a1a, bypassing the tooltip token. */
  .tooltip-layer .tooltip {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #3a424c !important;
  }
  /* The 百 badge raises the same box as an ::after instead of via .tooltip-layer. */
  a.nicopedia-article-anchor::after {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* The "有料" badge keeps a white pill while the broad legacy label rule lightens its text. */
  [class*="pay-program-label"] {
    background-color: #1a1a1a !important;
    border-color: #3a424c !important;
  }
  /* The divider between thumbnail and info row is the menu-area's border-TOP, not its bottom — soften every side. */
  [class*="menu-area"] { border-color: #262c33 !important; }

  /* The site colours provider-type badges by data-provider-type — official azure, channel gold — which the broad `-label` pass would flatten into one grey. The tag prefix lifts specificity to 0,1,1 so this beats that flatten (0,1,0), which lands LATER in the file. */
  span[data-provider-type="official"] { color: #559cff !important; }
  span[data-provider-type="channel"] { color: #d9a300 !important; }

  /* The nicoad point count is gold to mark it an ad-support metric, not a view count. Tag prefixes beat the later `[class*="-count"]` grey rule. */
  li[class*="nicoad-count"], li[class*="nicoad-count"] span { color: #d9a300 !important; }

  /* A 44%-white frosted caption bar with near-black text. */
  [class*="nicoad-frame"] [class*="message"] {
    background-color: rgba(20, 24, 29, 0.6) !important;
  }
  [class*="nicoad-frame"] [class*="message"],
  .advatisor, .advatisor [class*="name"] { color: #e6edf3 !important; }
  /* The supporter credit is one yellow phrase, but only the name is a `-name` element, so the legacy heading pass splits the line in two tones. The phrase colours itself — inherit it back. */
  .featured-content-marquee .user-name { color: inherit !important; }

  /* The ニコニ広告 / ギフト tiles default to a solid #fff square. Their glyph is a mask-image whose background-color IS the fill, so it is LIGHTENED — darkening it would erase it. Key on the shared ___secondary-button___ modifier, not the individual names: all four tiles in the row carry it. The 放送ネタ tile is a real img with a white-baked plate — raster policy, left alone. */
  button[class*="secondary-button"],
  button[class*="nicoad-button"], button[class*="gift-button"] {
    background-color: #2d333b !important;
  }
  button[class*="secondary-button"] [class*="symbol-mark"],
  button[class*="nicoad-button"] [class*="symbol-mark"],
  button[class*="gift-button"] [class*="symbol-mark"] {
    background-color: #c4cdd6 !important;
  }
  /* A 90%-white badge with #252525 text on the dark player stage. */
  [class*="watch-rejected"] [class*="value-area"] {
    background-color: #2d333b !important; color: #e6edf3 !important;
  }

  /* An <h2> whose only child is a banner PNG, on its own #eee fill — a light slab whenever the image 404s or has not arrived. NOTE (verified, do not "fix"): the banner ARTWORK is a white-background illustration with red accents and stays as-is; inverting it would flip those reds to cyan. */
  section[class*="konomi-tag-list-section"] > header > h2 {
    background-color: #14181d !important;
  }

  /* Hardcodes a #fafafa wrapper fill no token reaches; the cards and text inside are already dark-correct. */
  .official-live-ts-ranking { background-color: #14181d !important; }

  /* The carousel arrows are #f2f2f2 buttons with a near-black chevron, rested at opacity .2 so they read grey today — but any state raising the opacity paints a bright column. Dark button, light chevron: correct at every opacity. */
  [class*="page-selector"] { background-color: #2d333b !important; }
  [class*="page-selector"] svg, [class*="page-selector"] path { fill: #c4cdd6 !important; }

  /* These tooltips are an ::after with `content:`, styled #1a1a1a-on-#f2f2f2, which no token reaches. */
  [class*="program-menu-dock"] button::after,
  [class*="program-menu-dock"] a::after,
  [class*="ng-setting-button"]::after {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
    border-color: #3a424c !important;
  }

  /* Program-description section headings carry a 10px light-grey left accent bar and a 1px underline no token reaches. Scoped to the stable GA-namespace class (the hashed sibling is unstable). The bars are ALWAYS broadcaster-authored inline, so exempting inline borders to keep a broadcaster's hue is NOT an option: measured over 30 programs, 42 of 52 bars are the copy-paste default #d1d1d1 and only 10 are chromatic. Chroma reports the chromatic ones as `flattened` on every run; that is the intended trade. */
  .ga-ns-description div { border-color: #2d333b !important; }
  /* The pasted "blogparts" program embed ships an INLINE `background-color:#f6f6f6; border:solid 1px #d0d0d0` on its <iframe>, wider than the card it wraps. The document is same-origin so the card inside is already painted; clearing the element's own background lets the page backdrop show — the embedded html/body are transparent. */
  .ga-ns-description iframe {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  /* Broadcasters often wrap description headings in a light pastel pill relying on the site's dark default text, which our light-text pass overrides. Restore a dark label on any description element carrying its OWN inline background — keeping the broadcaster's colour — while the plain body (no inline bg) keeps the light text it needs. */
  .ga-ns-description [style*="background-color"],
  .ga-ns-description [style*="background-color"] * { color: #1a1a1a !important; }

  /* The INFO type-label pill keeps a #f2f2f2 fill no token reaches, under our label text pass; its label is already light. */
  .ga-ns-promotion-panel [class*="type-label"] {
    background-color: #2d333b !important;
  }

  /* The share promo balloon is a #e9f2ff callout no token reaches; its pointer is ::after's top border and its close glyph a mask-image whose background-color IS the X (lightened, not darkened). */
  .ga-ns-weak-balloon, section[class*="weak-balloon"] {
    background-color: #2d333b !important;
  }
  .ga-ns-weak-balloon::after, section[class*="weak-balloon"]::after {
    border-top-color: #2d333b !important;
  }
  .ga-ns-weak-balloon, .ga-ns-weak-balloon *,
  section[class*="weak-balloon"], section[class*="weak-balloon"] * {
    color: #e6edf3 !important;
  }
  .ga-ns-weak-balloon .close-button::before,
  section[class*="weak-balloon"] .close-button::before {
    background-color: #c4cdd6 !important;
  }
  /* The channel link announces itself only by turning #559cff on hover, and the heading pass pins it — without this it stops reading as clickable. */
  a.channel-name-anchor:hover { color: #5fb0e6 !important; }
  /* The 関連コンテンツ rows announce hover with a plate one step above the panel, and the `-card` surface arm pins them flat. */
  .ga-ns-related-content-card:hover { background-color: #262c33 !important; }
  /* Same shape on every live program card. */
  a.name-label:hover { color: #5fb0e6 !important; }
  /* Live home: the hero card's title turns blue under the pointer, and every card's broadcaster name turns blue when the pointer is on its provider ROW, not the name itself. Both are pinned by the `-title` / `-label` passes below. */
  .organization-super-important-program-card .program-title:hover,
  .program-provider-card .information:hover > a.name-label { color: #5fb0e6 !important; }
  /* Three of the home's card rails paint the SUMMARY blue on hover and their titles `inherit` it; the stage rail's white-on-artwork cards share the card markup but have no such rule, so the rails are named. */
  [class*="local-program-list-section"] .program-summary:hover > .program-title,
  [class*="nicoad-program-list-section"] .program-summary:hover > .program-title,
  [class*="ranking-program-list-section"] .program-summary:hover > .program-title { color: #5fb0e6 !important; }
  /* Live search / timetable / ranking lists: the list layout hovers the TITLE, the tile layouts the summary. */
  .program-card-list[data-program-card-view-mode="list"] .program-summary > .program-title:hover,
  .program-card-list[data-program-card-view-mode="tile"] .program-summary:hover > .program-title,
  [data-layout="tile"] .program-card-list .program-summary:hover > .program-title { color: #5fb0e6 !important; }

  /* Live broadcast-history embed — the iframe a www user page's 生放送 tab mounts. This theme reaches it (a live document), but it is a SEPARATE one: no host-page scan sees it. The month picker marks its choice with aria-pressed and the pager with aria-selected; both keep the active azure so the choice still reads. The prev/next arrows are a mask-image ::before whose background-color IS the glyph, so they are lightened — but the number buttons' ::before is the digit itself and takes the button's colour, so it must NOT be given a background. */
  .ga-ns-broadcast-history-page { background-color: #14181d !important; }
  /* Each card is separated by a 2px #e5e5e5 border-TOP on its <li>. The legacy `.BaseLayout *` border reset cannot reach it — that class is on the HOST page's body, and this is a separate document. */
  .ga-ns-broadcast-history-page li { border-color: #2d333b !important; }
  .ga-ns-broadcast-history-page button,
  .ga-ns-broadcast-history-page .program-category-type-label {
    background-color: #262c33 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .ga-ns-broadcast-history-page button[aria-pressed="true"],
  .ga-ns-broadcast-history-page button[aria-selected="true"] {
    background-color: #1f4a78 !important;
    color: #ffffff !important;
    border-color: #1f4a78 !important;
  }
  .ga-ns-broadcast-history-page button[data-name="prev"]::before,
  .ga-ns-broadcast-history-page button[data-name="next"]::before {
    background-color: #c4cdd6 !important;
  }
  /* The picker's header controls (前月へ / 次月へ / リセット) are bare chrome, not pills. Additive override rather than a :not() arm, whose specificity would then outrank the later same-specificity rules. */
  .ga-ns-broadcast-history-page [class*="year-month-picker"] [class*="-button"] {
    background-color: transparent !important;
    border-color: transparent !important;
  }
  .ga-ns-broadcast-history-page [class*="message"] { color: #c4cdd6 !important; }

  /* Selected segmented-control pill (search type tabs, comment-vs-tag toggle). Brand azure, not an elevated grey: grey reads only 1.14:1 against the unselected pills' 10%-white track. Scoped to the token's own class so only the SELECTED pill is touched. */
  [class*="transparentWhite.A95"] {
    background-color: #1f4a78 !important;
    color: #e6edf3 !important;
    fill: #e6edf3 !important;
  }
  [class*="transparentWhite.A95"] svg,
  [class*="transparentWhite.A95"] path { fill: #e6edf3 !important; }

  /* Common top header bar (shared chrome) + its two flyouts */
  .CommonHeader, [class*="CommonHeader"] { background-color: #0d1117 !important; }
  header [class*="common-header-"] { color: #e6edf3; }

  /* The bar hosts two flyouts — the "その他" mega-dropdown and the account panel behind the avatar chevron — closed at load and hardcoding their own light surfaces and labels. Nothing inside is hookable by name: the roots and wrappers are pure hashed divs, and the service rows share `pos=header_servicelink` with the eight ALWAYS-VISIBLE nav links of the bar itself. DEPTH is the discriminator that holds: measured live, the bar's own chrome never nests more than six divs deep (nav links at four) while everything inside either flyout starts at seven. A plain descendant chain selects the flyout interiors exactly and, being CSS2, survives the .org.css sanitizer that strips relational selectors. The bar mounts under TWO ids — `#CommonHeader` on www, `#common-header` on live (id selectors are case-sensitive) — at the same depth, so every rule below is stated for each. */
  #CommonHeader div div div div div div div,
  #CommonHeader div div div div div div div a,
  #common-header div div div div div div div,
  #common-header div div div div div div div a {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  #CommonHeader div div div div div div div a *,
  #CommonHeader div div div div div div div span,
  #CommonHeader div div div div div div div label,
  #common-header div div div div div div div a *,
  #common-header div div div div div div div span,
  #common-header div div div div div div div label {
    color: #c4cdd6 !important;
  }
  #CommonHeader div div div div div div div a:hover,
  #common-header div div div div div div div a:hover {
    background-color: #262c33 !important;
  }
  /* One thing in the always-visible bar reaches seven divs too: the wrapper pair around the account avatar. It is the FIRST child of the avatar button, whereas the account panel and its click-scrim are later children, so a child-chain + :first-child isolates it. */
  #CommonHeader > div > div > div > div > div > div:first-child div,
  #common-header > div > div > div > div > div > div:first-child div {
    background-color: transparent !important;
  }
  /* The panel's two CTAs are anchors in the same subtree and carry the same `pos=userpanel` marker as the plain rows, so the only discriminator is where they point: account.nicovideo.jp. Same chain plus one attribute, so this lands later AND heavier. */
  #CommonHeader div div div div div div div a[href*="account.nicovideo.jp/login"],
  #common-header div div div div div div div a[href*="account.nicovideo.jp/login"] {
    background-color: #498dca !important; color: #ffffff !important;
  }
  #CommonHeader div div div div div div div a[href*="account.nicovideo.jp/register"],
  #common-header div div div div div div div a[href*="account.nicovideo.jp/register"] {
    background-color: #e5a100 !important; color: #ffffff !important;
  }

  /* The suggestion panel hardcodes #fff and exists only while a query is typed. */
  .nicolib-SuggestSearch {
    background-color: #1c2128 !important; border-color: #2d333b !important;
  }
  .nicolib-SuggestSearch-item.active, .nicolib-SuggestSearch-item:hover,
  .nicolib-SuggestSearch-item > button:hover {
    background-color: #262c33 !important;
  }
  /* Opens onto a #f5f5f5 sheet. */
  .CrossSearch-pullDownList {
    background-color: #1c2128 !important; border-color: #2d333b !important;
  }
  .CrossSearch-pullDownList li:hover { background-color: #262c33 !important; }
  /* The scope selector marks the current scope with a #555 fill, and the panel rule paints all three alike. Azure, not an elevated grey — grey sits only 1.6:1 above the row's own track. */
  /* Must stay BEFORE the active rule below — the two tie on specificity and the selected row has to keep its azure while the pointer is on it. */
  .CrossSearch-rowService:hover { background-color: #262c33 !important; }
  .CrossSearch-rowService.active {
    background-color: #1f4a78 !important; color: #e6edf3 !important;
  }
  /* Below 1100px this single trigger replaces the three scope rows above and is the ONLY scope control at those widths. */
  .CrossSearch-pullDownButton { background-color: #262c33 !important; }
  .CrossSearch-pullDownButton:hover,
  .CrossSearch-pullDownButton.active { background-color: #2d333b !important; }

  /* The ヘッダー追従 switch is the shared common-header component, so it rides on EVERY page of both hosts and its state persists in the visitor's own storage. Its two states are two hashed class pairs, so key on the checkbox instead: the header holds exactly one, and its two siblings are the track then the knob. The ON knob's 2px border IS its own blue natively — the blanket border reset would turn it into a dark ring inside the disc. */
  #CommonHeader label > input[type="checkbox"] + span,
  #common-header label > input[type="checkbox"] + span {
    background-color: #3a424c !important;
  }
  #CommonHeader label > input[type="checkbox"] + span + span,
  #common-header label > input[type="checkbox"] + span + span {
    background-color: #8b949e !important; border-color: #8b949e !important;
  }
  #CommonHeader label > input[type="checkbox"]:checked + span,
  #common-header label > input[type="checkbox"]:checked + span {
    background-color: #1f4a78 !important;
  }
  #CommonHeader label > input[type="checkbox"]:checked + span + span,
  #common-header label > input[type="checkbox"]:checked + span + span {
    background-color: #4990e2 !important; border-color: #4990e2 !important;
  }

  /* LEGACY DOM — home (video_top) + profiles (UserPage). Stable structural / semantic classes only. */

  /* Base layout shells */
  .BaseLayout, .BaseUniLayout,
  body.BaseLayout, body.BaseUniLayout {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }
  .BaseLayout-container, .BaseLayout-contents, .BaseLayout-main,
  .BaseLayout-header, .BaseLayout-sidebar, .BaseLayout-block,
  .BaseLayout-billboard, .BaseUniLayout-container, .BaseUniLayout-contents,
  .BaseUniLayout-main, .BaseUniLayout-block {
    background-color: transparent !important;
  }

  /* Soften every light border across the legacy DOM */
  .BaseLayout *, .BaseUniLayout * { border-color: #262c33 !important; }

  /* Site / category header strip on the home page */
  .GlobalHeader, .HeaderContainer, .SiteHeader, #siteHeaderNotification,
  .VideoTopHeaderContainer {
    background-color: #0d1117 !important;
  }
  .VideoTopGenreListContainer, .GenreListContainer,
  [class*="GenreListContainer"] {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }
  .VideoTopGenreListContainer-item, [class*="GenreListContainer-item"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .VideoTopGenreListContainer-item.is-current,
  [class*="GenreListContainer-item"].is-current {
    background-color: #262c33 !important;
    color: #e6edf3 !important;
  }
  .VideoTopGenreListContainer-item:hover,
  [class*="GenreListContainer-item"]:hover { background-color: #1f262e !important; }

  /* Left navigation / system menu + side drawer rail */
  .SystemMenuContainer, .SideMenuContainer, .GlobalNavigation,
  [class*="SystemMenu"], [class*="SideMenu"], [class*="LeftMenu"] {
    background-color: transparent !important;
  }
  .SystemMenuContainer a, .SideMenuContainer a,
  [class*="SystemMenu"] a, [class*="SideMenu"] a { color: #c4cdd6 !important; }
  .SystemMenuContainer a:hover, .SideMenuContainer a:hover { color: #e6edf3 !important; }

  /* The drawer's inner surfaces are hashed, so the whole subtree is repainted. */
  .NC-VideoMenuDrawerPlaceHolder, .NC-WebDrawer, .NC-VideoMenu,
  [class*="VideoMenuDrawer"], [class*="WebDrawer"], [class*="VideoMenu"],
  .NC-VideoMenuDrawerPlaceHolder *, .NC-WebDrawer *, [class*="VideoMenuDrawer"] * {
    background-color: #1c2128 !important;
  }
  .NC-VideoMenuDrawerPlaceHolder *, .NC-WebDrawer *, [class*="VideoMenuDrawer"] * {
    border-color: #262c33 !important;
  }
  .NC-VideoMenuDrawerPlaceHolder a, .NC-WebDrawer a, [class*="VideoMenu"] a {
    color: #c4cdd6 !important; background-color: transparent !important;
  }
  .NC-VideoMenuDrawerPlaceHolder a:hover, .NC-WebDrawer a:hover { color: #e6edf3 !important; }
  /* Active / hovered drawer rows */
  .NC-VideoMenuDrawerPlaceHolder [class*="active"],
  .NC-WebDrawer [class*="active"] { background-color: #262c33 !important; }
  /* Row icons are inline SVGs whose shapes carry a hardcoded fill PRESENTATION ATTRIBUTE (#3B3B3B, plus #252525, #1a1a1a, #000), which no token reaches. The row's hover needs restating too: the site paints label AND icon #3b3b3b over a 5%-black wash. */
  .NC-VideoMenuDrawerPlaceHolder svg path, .NC-VideoMenuDrawerPlaceHolder svg circle,
  .NC-VideoMenuDrawerPlaceHolder svg rect, .NC-VideoMenuDrawerPlaceHolder svg polygon,
  .NC-WebDrawer svg path, .NC-WebDrawer svg circle,
  .NC-WebDrawer svg rect, .NC-WebDrawer svg polygon { fill: #c4cdd6 !important; }
  .NC-VideoMenuDrawerPlaceHolder a:hover *, .NC-VideoMenuDrawerPlaceHolder button:hover *,
  .NC-WebDrawer a:hover *, .NC-WebDrawer button:hover * { color: #e6edf3 !important; }
  .NC-VideoMenuDrawerPlaceHolder a:hover svg path,
  .NC-VideoMenuDrawerPlaceHolder button:hover svg path,
  .NC-WebDrawer a:hover svg path, .NC-WebDrawer button:hover svg path {
    fill: #e6edf3 !important;
  }
  .NC-VideoMenuDrawerPlaceHolder a:hover > *,
  .NC-WebDrawer a:hover > * { background-color: #262c33 !important; }
  /* The rail's language picker is an Ark UI select. Its trigger rests in the rail's own #1a1a1a ink, and its listbox is portalled under <body> — outside the drawer subtree — as a #fff sheet with #1a1a1a rows and a black-wash hover. Scoped to the legacy body class: the modern pages' selects are token-driven. */
  .NC-VideoMenuDrawerPlaceHolder [data-scope="select"][data-part="trigger"],
  .NC-VideoMenuDrawerPlaceHolder [data-scope="select"][data-part="value-text"] { color: #c4cdd6 !important; }
  .NC-VideoMenuDrawerPlaceHolder [data-scope="select"][data-part="trigger"]:hover { background-color: #262c33 !important; }
  .BaseLayout [data-scope="select"][data-part="content"],
  .BaseUniLayout [data-scope="select"][data-part="content"] {
    background-color: #1c2128 !important; box-shadow: 0 0 8px #0d1117 !important;
  }
  .BaseLayout [data-scope="select"][data-part="item"],
  .BaseUniLayout [data-scope="select"][data-part="item"] { color: #c4cdd6 !important; }
  .BaseLayout [data-scope="select"][data-part="item"]:hover,
  .BaseLayout [data-scope="select"][data-part="item"][data-highlighted],
  .BaseUniLayout [data-scope="select"][data-part="item"]:hover,
  .BaseUniLayout [data-scope="select"][data-part="item"][data-highlighted] {
    background-color: #262c33 !important; color: #e6edf3 !important;
  }

  /* Each home section is a stable *Container; the cards inside are hashed React nodes, so the subtree is reset dark and the cards repainted on top. */
  .RecommendAreaContainer, .RecommendVideoContainer, .ForYouRankingContainer,
  .NewArrivalVideosContainer, .NicoadVideosContainer, .OnTvAnimeVideosContainer,
  .TagPushVideosContainer, .HotTagsContainer, .NewsNotificationContainer,
  .NicoNewsContainer, .ViewHistoriesContainer, .FollowingVideosContainer,
  .BunsContainer, .LivePlayerContainer, .VideoIntroductionAreaContainer,
  .FooterContainer,
  .RecommendAreaContainer *, .ForYouRankingContainer *, .NewArrivalVideosContainer *,
  .NicoadVideosContainer *, .OnTvAnimeVideosContainer *, .TagPushVideosContainer *,
  .HotTagsContainer *, .NewsNotificationContainer *, .NicoNewsContainer *,
  .ViewHistoriesContainer *,
  .FollowingVideosContainer *, .VideoIntroductionAreaContainer *, .FooterContainer * {
    background-color: transparent !important;
  }
  /* The actual elevated cards in those sections */
  .NC-NegativeFeedbackedVideoCard, [class*="VideoCard"], [class*="MediaObject"],
  .NewsNotificationList-item, .TagWithVideoItem, .ForYouRankingContainer-videoItem,
  .NewArrivalVideosContainer-list > *, .NicoadVideosContainer-list > *,
  .NicoNewsContainer-photoNews {
    background-color: #1c2128 !important;
  }
  /* The well also carries an inline data:image/svg+xml placeholder as its background-IMAGE, painting over the colour. The article photo is a separate child div, so dropping the image only ever removes the placeholder. */
  /* The photo-news card is one anchor; its title inherits the #0080ff hover. */
  a.NicoNewsContainer-photoNewsContent:hover .NicoNewsContainer-photoNewsTitle { color: #5fb0e6 !important; }
  .NicoNewsContainer-photoNewsThumbnail {
    background-color: #262c33 !important;
    background-image: none !important;
  }
  /* Empty thumbnail wells / skeletons. Most bars carry no "Skeleton" class of their own, so matching the container AND every descendant covers the family in one rule. That can never repaint real artwork: a skeleton container holds no content and loses its class the moment its data lands (measured across eight page types with the API stalled: zero img/video/anchor descendants under any `[class*="Skeleton"]`). Attribute matching is case-sensitive, so the lowercase `-skeleton` ad-slot placeholders need their own arm — and it stays OFF descendants, because a real creative loads inside those slots. background-image goes with it: several wells carry the near-white "no thumbnail" SVG, which paints over any colour. */
  .NC-VideoCardSkeleton-barContainer,
  [class*="Skeleton"] {
    background-color: #262c33 !important;
    background-image: none !important;
  }
  [class*="Skeleton"] * {
    background-color: #262c33 !important;
    background-image: none !important;
  }
  /* The bars are always leaf nodes. Lifting only those one step keeps the site's panel / bar pair, so a loading list still reads as a skeleton instead of one flat slab. */
  [class*="Skeleton"] *:empty { background-color: #2d333b !important; }
  [class*="-skeleton"] { background-color: #262c33 !important; }
  /* The feed's section separators are borders on ::before / ::after, which the `.BaseLayout *` reset cannot reach — a `*` selector never matches a pseudo-element. Listed one by one on purpose: a blanket pseudo-border reset would also flatten the orange .Tabs-tab.is-active::after accent and the header's border-triangle carets, which are art. */
  .ContentsDigestFrame::before, .ContentsDigestFrame::after,
  .ChannelContainer::before, .EnhancedContainer::before,
  .TextListFrame-item::before, .CrossSearch-pullDownService::before {
    border-color: #2d333b !important;
  }
  /* Both render a bare #fff shell while their data is in flight and unmount if it never arrives, so no loaded-page scan sees them. */
  .PublishedEventArticlesContainer, .SponsorsContainer {
    background-color: #1c2128 !important;
  }
  /* Both carry the site's "no thumbnail" SVG as a background-IMAGE, painting OVER the dark fill. The real thumbnail loads on the child .Thumbnail-image, never on these. */
  .ContentItemSkeleton-thumbnail, .ContentsDigestFrame-contentThumbnail {
    background-image: none !important;
  }
  /* The same placeholder sits deeper, on `.Thumbnail-image` itself, whose REAL artwork arrives as an INLINE `style="background-image:url(…)"` on lazy-load. Keying on the ABSENCE of that attribute removes only the placeholder — artwork always carries it (measured on home: 24 placeholders, none with a style attribute; 75 real ones, all with it). */
  .Thumbnail-image:not([style]) { background-image: none !important; }
  /* Same placeholder, second component: the 2026 stage rows use `.NC-Thumbnail-image`, a DIFFERENT class token `.Thumbnail-image` cannot match, with the same lazy inline `style` — so the same absence-of-style guard applies (15/15 wells carry it, none has a style attribute). */
  .NC-Thumbnail-image:not([style]) { background-image: none !important; }
  /* A natively transparent anchor whose class contains "VideoCard", so the arm above paints it opaque. Override additively rather than adding :not() to that arm, whose specificity would then rise and outrank later same-specificity !important rules. */
  [class*="hoverMenuPositioner"] { background-color: transparent !important; }

  /* live program cards paint a white "no thumbnail" SVG under the real <img>; the background layer is ONLY ever this placeholder, so dropping it cannot touch artwork. The video-side twin is inverted instead — safe only because that element has no children, where a.preview wraps the <img> and the LIVE / start-time badges. Two plain classes rather than a Level 4 relational selector, which the .org.css sanitizer strips. */
  a.preview.program-preview {
    background-image: none !important;
    background-color: #262c33 !important;
  }
  /* A second variant of the same well that `a.preview.program-preview` cannot match, with a different WHITE placeholder painted `no-repeat` at intrinsic size — a 4:3 thumbnail over a 16:9 well leaves white letterbox bars. */
  .preview.content-preview {
    background-image: none !important;
    background-color: #262c33 !important;
  }

  /* A SCHEDULED program's start-time badge is a 90%-white pill no token reaches; the child LIVE badge keeps its red. A LIVE-now card's .state is sized exactly to that red badge, so the same rule is invisible there — no relational selector the .org.css sanitizer would strip. */
  .preview [class*="state___"] { background-color: rgba(20, 24, 29, 0.85) !important; }
  .preview [class*="start-at___"] { color: #e6edf3 !important; }

  /* TopPage (2026 home) surfaces the token/legacy passes miss: the "stage" texture image, the stage cards, the billboard slot and the footer. */
  .StageBackground {
    background-image: none !important; background-color: transparent !important;
  }
  /* An inline #fafafa plus a decorative film-strip PNG on a full-width backdrop; the cards inside are transparent, so the cream floods the row. */
  .EventDecorationContainer, .EventDecorationContainer-background,
  .EventDecorationContainer-backgroundImage, .EventDecorationContainer-footer {
    background-image: none !important; background-color: transparent !important;
  }
  .ContentsPickupContainer, .ContentsPickupContainer-waku,
  .ContentsPickupContainer-wakuItems { background-color: transparent !important; }
  /* The live-event window is a #fff slab that only renders while a campaign sets data-wktk-show; its title/blurb are already lightened by the heading and description passes, which also pin the title's #0080ff hover. The player is an ext.live iframe, out of reach; its failure plate is the site's own #252525 with #555 text. */
  .LiveWindowContainer { background-color: #1c2128 !important; }
  .LiveWindowContainer-metaLink:hover > .LiveWindowContainer-metaTitle { color: #5fb0e6 !important; }
  .ExtPlayerView-errorText { color: #c4cdd6 !important; }
  /* "Sticker"-type headings: a near-black label wearing a 4px #fafafa `-webkit-text-stroke`. Our text pass flips the FILL but nothing reaches the stroke, so fill and outline end up the same tone and the letterforms render hollow. */
  .ContentsPickupContainer-wakuTitleText { -webkit-text-stroke-color: #14181d !important; }
  .StageRecommendLiveCard, .StageRequestedContentCard, .StageEventContentCard {
    background-color: #1c2128 !important;
  }
  .TopPage-footer { background-color: #14181d !important; }
  .TopPage-middleBillboardAdSection { background-color: #161b21 !important; }
  /* A solid #fff bar. Its own link text is the site's semantic blue and clears 4.5:1 on the repainted surface, so only the bar is touched. */
  /* …and it is an OUTLINED notice: the #0080ff border matches its blue icon and link text, and the `.BaseLayout *` reset would grey it. */
  .OneLineNewsContainer {
    background-color: #1c2128 !important; border-color: #0080ff !important;
  }
  /* The BLACK logo variant, a data-URI SVG whose every path is #252525. Single-colour glyph, so inverting the layer is exact; the sibling _white variant is already correct and left alone. */
  .NiconicoLogo_black { filter: invert(1) !important; }

  /* The hero pickup title and the section "see more" links sat dark-on-dark */
  .AuroraVisionCard-metaPickUpComment { color: #e6edf3 !important; }
  /* Hovering the hero card turns the title #0080ff — the card's only hover affordance — and the `!important` above would swallow it. Two classes to outrank that rule. */
  .AuroraVisionCard:hover .AuroraVisionCard-metaPickUpComment { color: #5fb0e6 !important; }
  /* A #fff button, so the light label needs an elevated dark fill under it. */
  .SeeMoreLink-text {
    background-color: #2d333b !important; border-color: #3a424c !important;
  }
  .SeeMoreLink-text, .SeeMoreLink-text span, a.SeeMoreLink span { color: #c4cdd6 !important; }
  /* Every hover affordance on the home feed is the site's #0080ff / #4a90e2 on otherwise-plain text, and the body/heading passes are !important, so each cue has to be restated here. Theme accent rather than the site's blues, which reach only ~3.7:1 here; every selector carries the hover pseudo, so it outranks the flat pass. */
  .SeeMoreLink-text:hover {
    border-color: #5fb0e6 !important;
  }
  .SeeMoreLink-text:hover, .SeeMoreLink-text:hover span,
  a.SeeMoreLink:hover .SeeMoreLink-text span { color: #5fb0e6 !important; }
  .SeeMoreLink-text:hover svg, .SeeMoreLink-text:hover path { fill: #5fb0e6 !important; }
  .ContentsDigestFrame-card:hover .ContentsDigestFrame-cardMetaTitle,
  .FrameTitleLink:hover > .FrameTitleLink-titleText { color: #5fb0e6 !important; }
  .NicoNewsContainer .Tabs-tab, .NicoNewsContainer-skeleton .Tabs-tab { color: #8b949e !important; }
  /* The active tab is a solid orange pill + white label, blanked by the `.NicoNewsContainer *` neutraliser and the text pass. The fill is toned to a burnt #a85400 so the white label clears AA, where pure #ff8000 would not. Hover shares that orange. */
  .NicoNewsContainer .Tabs-tab.is-active,
  .NicoNewsContainer .Tabs-tab:hover {
    background-color: #a85400 !important; color: #ffffff !important;
  }
  /* A #fff pill with an #ff8000 label over the article photo, cleared by the neutraliser. Dark pill so it reads over artwork; the orange matches the count icon's raster. */
  a.NicoNewsContainer-commentCount {
    background-color: rgba(20, 24, 29, 0.85) !important; color: #ff8000 !important;
  }

  /* `lightgray` fill behind a lazily-loaded image, so grey discs flash before the avatars land. The avatar paints over this. */
  .NC-OwnerIcon-image { background-color: #262c33 !important; }

  /* ---- Profile / user page components ---- */
  .UserPage-header, .UserPage-content, .UserDetailsHeader, .UserDetailsContainer,
  .UserDetailsCard, [class*="UserDetails"], .UserIcon, .MainMenuContainer,
  .MainMenuContainer-menu, .NC-Tabs, .TimelineItem, .TimelineItem-content,
  .CrossSearch-form, .CrossSearch-rowSelector, .CrossSearch-rowService,
  .SearchBox-option, .Dropdown-menu, .Dropdown-content,
  [class*="UserPage-"], [class*="Timeline"] {
    background-color: #1c2128 !important;
  }
  .UserDetailsHeader, .MainMenuContainer { background-color: transparent !important; }
  /* The profile header's bottom separator is a 2px light ::after line, not a border. */
  .UserDetailsContainer::after { background-color: #262c33 !important; }
  /* A transparent→#fff scroll-fade over the clipped rows, remapped to the card surface so the clip still reads. */
  .ExpandBoxButton-overlay {
    background-image: linear-gradient(rgba(28, 33, 40, 0) 0px, #1c2128) !important;
  }
  /* The もっと見る toggle is label + chevron in one #999 that turns #0080ff on hover (also when the pointer is on the fade above it). The `Description` pass pins only the label, so the pair would split: chevron blue, label grey. */
  .ExpandBoxButton-icon { fill: #c4cdd6 !important; }
  .ExpandBoxButton:hover, .ExpandBoxButton-overlay:hover + .ExpandBoxButton { color: #5fb0e6 !important; }
  .ExpandBoxButton:hover .ExpandBoxButton-icon,
  .ExpandBoxButton-overlay:hover + .ExpandBoxButton .ExpandBoxButton-icon { fill: #5fb0e6 !important; }
  /* Same fade, HORIZONTAL and on a pseudo. A pseudo's background-IMAGE is invisible to both the element-bg walk and the pseudo-colour probe. */
  .NC-MylistMediaObject-thumbnail::before {
    background-image: linear-gradient(90deg, rgba(28, 33, 40, 0), #1c2128) !important;
  }
  /* Third instance of the same fade. The 急上昇中のタグ section is served with `data-hide-hrc` (display:none) outside Japan, so no scan run from here renders it. */
  .TagWithVideoItem-nicopediaLink {
    background-image: linear-gradient(90deg, rgba(28, 33, 40, 0), #1c2128 20px) !important;
  }
  /* The clipped summary is #666 on its own white tile. Same region gate as the gradient above. */
  .TagWithVideoItem-articleBody { color: #c4cdd6 !important; }

  /* Both popovers are closed at load and keep a #fff root no token reaches. */
  .Dropdown, .NC-ThreePointMenu-menu {
