  /* The pill is a link and doubling the wash's alpha is its whole hover state; the restored tints above are fixed values, so that doubling has nowhere to happen. */
  a.UserDetailsRepresentedAchievement_pleasure:hover { background-color: rgba(20, 184, 102, 0.32) !important; }
  a.UserDetailsRepresentedAchievement_hope:hover { background-color: rgba(26, 192, 229, 0.32) !important; }
  a.UserDetailsRepresentedAchievement_star:hover { background-color: rgba(235, 71, 153, 0.32) !important; }
  a.UserDetailsRepresentedAchievement_legend:hover { background-color: rgba(242, 185, 13, 0.32) !important; }
  /* Turns #0080ff on hover, pinned by the legacy body pass. */
  a.TimelineItem-senderName:hover { color: #5fb0e6 !important; }
  /* One anchor whose title and detail label inherit the same #0080ff hover; both pinned by the heading / label passes. */
  a.TimelineItem-contentBody:hover .TimelineItem-contentTitle,
  a.TimelineItem-contentBody:hover .TimelineItem-contentDetailLabel { color: #5fb0e6 !important; }
  /* This CTA is an <a>, so the broad `.BaseUniLayout a` grey rule (no !important, 0,1,1) flattens its label while the "フォロー" <button> beside it keeps the site's blue. Specificity plus !important beat that rule and make it deterministic. */
  a.CreatorSupportButton, a.CreatorSupportButton .CreatorSupportButton-text,
  a.CreatorSupportButton .CreatorSupportButton-icon { color: #0080ff !important; }
  /* Same outlined-blue button as フォロー; the blanket border reset greys its #0080ff border. */
  a.CreatorSupportButton { border-color: #0080ff !important; }
  /* Hover fills the outline solid and flips the label white. The element also carries a `UserDetails*` class, so the profile-surface rule pins the fill and the blue-ink restore above pins the label — both halves must be restated together, or the label sits blue-on-blue. The `_supporting` hover below is heavier and keeps its own grey. */
  a.CreatorSupportButton:hover { background-color: #0080ff !important; }
  a.CreatorSupportButton:hover, a.CreatorSupportButton:hover .CreatorSupportButton-text,
  a.CreatorSupportButton:hover .CreatorSupportButton-icon { color: #ffffff !important; }
  /* An OUTLINED button: the site's #0080ff border with blue star + label. The label survives (a <button>, untouched by the anchor rule) but the blanket `.BaseUniLayout *` reset greys the frame. */
  button.FollowButton { border-color: #0080ff !important; }
  /* The list rows carry `.NC-FollowButton`, a separate class token `.FollowButton` cannot match, so no rule above reaches its #0080ff frame, greyed by the blanket reset. Its FOLLOWING state is a #e9e9e9 pill with #666 ink and only ever renders for a logged-in viewer. */
  button.NC-FollowButton { border-color: #0080ff !important; }
  /* On a mylist-index row the button also carries a `MediaObject` class, so the card-surface rule pins the fill and only the label flips. The following-state hover below is heavier and still wins. */
  button.NC-FollowButton:hover {
    background-color: #0080ff !important; border-color: #0080ff !important;
  }
  button.NC-FollowButton[data-is-following="true"] {
    background-color: #2d333b !important;
    border-color: #3a424c !important;
    color: #c4cdd6 !important;
  }
  button.NC-FollowButton[data-is-following="true"]:hover {
    background-color: #3a424c !important; color: #e6edf3 !important;
  }
  /* Both "done" states swap in an #e5e5e5/#666 pill, and `.CreatorSupportButton_supporting` also carries a `UserDetails*` class, so the profile surface rule and the blue-ink restore apply to BOTH states — 支援中 would render pixel-identical to サポートする. One dark chip that reads as already-done beside the outlined CTA. Only a logged-in viewer renders either state. */
  button.FollowButton.FollowButton_following,
  a.CreatorSupportButton.CreatorSupportButton_supporting {
    background-color: #2d333b !important; border-color: #3a424c !important;
  }
  button.FollowButton.FollowButton_following,
  button.FollowButton.FollowButton_following *,
  a.CreatorSupportButton.CreatorSupportButton_supporting,
  a.CreatorSupportButton.CreatorSupportButton_supporting * {
    color: #c4cdd6 !important;
  }
  button.FollowButton.FollowButton_following:hover,
  a.CreatorSupportButton.CreatorSupportButton_supporting:hover {
    background-color: #3a424c !important;
  }

  /* Google Funding Choices consent manager, mounted in the page (not an iframe) as .fc-consent-root; on live it is the first thing a logged-out visitor sees. Every surface is hardcoded #fff with dark ink — sheet, Manage-options and vendor sub-panels, and the recall chip in the bottom-left corner. The #1967d2 primary CTA keeps its brand fill (white label, ~5:1), but the SAME blue as LINK ink reaches only ~2.6:1 on the dark sheet, so links move to the theme azure. EVERY Funding Choices declaration is !important and scoped as ".fc-consent-root <class>", so a bare .fc-dialog arm loses on specificity — each arm restates the ancestor (and, for the headline/title, the h1.fc-… compound) to tie it and win on source order. */
  .fc-consent-root div, .fc-consent-root p, .fc-consent-root h1,
  .fc-consent-root h2, .fc-consent-root span, .fc-consent-root li,
  .fc-consent-root ul, .fc-consent-root button {
    color: #c4cdd6 !important;
  }
  .fc-consent-root a:link, .fc-consent-root a:visited { color: #5fb0e6 !important; }
  .fc-consent-root .fc-dialog,
  .fc-consent-root .fc-dialog-header,
  .fc-consent-root .fc-choice-dialog-header,
  .fc-consent-root .fc-faq-contents,
  .fc-consent-root .fc-preference-container,
  .fc-consent-root .fc-help-dialog,
  .fc-consent-root .fc-faq-header .fc-faq-icon,
  .fc-consent-root .fc-data-preferences-dialog .fc-navigation-button,
  .fc-consent-root .fc-help-dialog .fc-help-dialog-button-container,
  #__ap_gfc_consent_box_btn__ {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-dialog .fc-header h1,
  .fc-consent-root .fc-dialog .fc-header h1.fc-dialog-headline,
  .fc-consent-root .fc-help-dialog h1,
  .fc-consent-root .fc-stacks .fc-stack-name,
  .fc-consent-root .fc-faq-header .fc-faq-label,
  .fc-consent-root .fc-preference-container .fc-preference-title h2 {
    color: #e6edf3 !important;
  }
  .fc-consent-root .fc-header-text,
  .fc-consent-root .fc-dialog .fc-header .fc-header-text,
  .fc-consent-root .fc-dialog-header p,
  .fc-consent-root .fc-dialog .fc-header h2,
  .fc-consent-root .fc-dialog .fc-header h2.fc-dialog-title,
  .fc-consent-root .fc-dialog .fc-footer p,
  .fc-consent-root .fc-faq-contents .fc-faq-item,
  .fc-consent-root .fc-faq-contents .fc-faq-item-title,
  .fc-consent-root .fc-preference-divider p,
  .fc-consent-root .fc-preference-container .fc-preference-description,
  .fc-consent-root .fc-preference-container .fc-preference-slider-label,
  .fc-consent-root .fc-data-preferences-dialog .fc-body p,
  .fc-consent-root .fc-data-preferences-dialog .fc-noneditable-body p,
  .fc-consent-root .fc-help-dialog .fc-help-dialog-contents div,
  .fc-consent-root .fc-help-dialog .fc-help-dialog-contents li,
  .fc-consent-root .fc-help-dialog .fc-help-dialog-contents p,
  .fc-consent-root .fc-preference-container .fc-preference-description ul,
  .fc-consent-root .fc-preference-container .fc-preference-description ul > li,
  .fc-consent-root .fc-preference-container .fc-preference-description ul > li b {
    color: #8b949e !important;
  }
  .fc-consent-root .fc-dialog .fc-footer a,
  .fc-consent-root .fc-dialog .fc-footer a:visited,
  .fc-consent-root .fc-dialog .fc-footer a.fc-footer-link-v2,
  .fc-consent-root .fc-dialog .fc-footer a.fc-footer-link-v2:visited,
  .fc-consent-root .fc-navigation-button .fc-navigation-button-label,
  .fc-consent-root .fc-manage-options-third-button-label,
  .fc-consent-root .fc-preference-container .fc-preference-description a,
  .fc-consent-root .fc-preference-container .fc-preference-description a:visited,
  .fc-consent-root .fc-help-dialog .fc-help-dialog-contents a,
  .fc-consent-root .fc-help-dialog-close-button .fc-help-dialog-close-button-label {
    color: #5fb0e6 !important;
  }
  .fc-consent-root .fc-footer-buttons-divider,
  .fc-consent-root .fc-preference-divider,
  .fc-consent-root .fc-faq-contents .fc-faq-item-dot,
  .fc-consent-root .fc-preference-container .fc-preference-container-divider {
    background-color: #2d333b !important;
  }
  /* The recall chip's glyph is a base64 raster with no addressable fill, but measures perfectly achromatic (max channel spread 0 across all 2500 px), so inverting it is hue-lossless. */
  #__ap_gfc_consent_box_btn__ img {
    filter: invert(1) !important; border-color: #2d333b !important;
  }

  /* Feedback form (www.nicovideo.jp/feedback/*): its own literal-colour sheet, no design token. `.FeedbackPage a:link` is (0,2,1), so the `.BaseUniLayout a` pass below cannot take the link ink without !important. The validation banner ships display:none; the confirmation panel renders only on the form's POST response, which nothing links to. */
  .FeedbackPage a, .FeedbackPage a:link, .FeedbackPage a:hover {
    color: #5fb0e6 !important;
  }
  .FeedbackPage .errorMessageContainer {
    background: #2b1d20 !important;
    border-bottom-color: #5a2f2f !important;
  }
  .FeedbackPage .errorMessageContainer p,
  .FeedbackPage .errorMessageLink a,
  .FeedbackPage .errorMessageLink a:after,
  .FeedbackPage .notice,
  .FeedbackPage .redText { color: #ff5c5c !important; }
  .FeedbackPage .confirmationDetails {
    background: #1c2128 !important;
    border-color: #3a424c !important;
  }
  /* Disabled submit keeps a muted label so it still reads as unavailable next to
     the enabled #006fff variant. */
  .FeedbackPage input[type="submit"][disabled].confirmButton {
    background: #2d333b !important;
    color: #8b949e !important;
  }
  .FeedbackPage input[type="submit"].backButton {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #3a424c !important;
  }

  /* Search box (legacy header) */
  .SearchInput, .CrossSearch input, .SearchField input,
  input[type="text"], input[type="search"], input[type="email"],
  input[type="password"], textarea, select {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  ::placeholder { color: #8b949e !important; opacity: 1 !important; }
  .SearchInput::placeholder, .CrossSearch input::placeholder { color: #8b949e !important; }

  /* Links */
  .BaseLayout a, .BaseUniLayout a { color: #c4cdd6; }
  .BaseLayout a:hover, .BaseUniLayout a:hover { color: #e6edf3; }

  /* Misc light greys used as separators / rails in legacy DOM */
  hr, .Divider, [class*="Divider"], [class*="Separator"] {
    border-color: #2d333b !important; background-color: #2d333b !important;
  }
  /* This 6px section rule's stripes live only in a repeating-linear-gradient, so the background-COLOR above never touches them. Restated in the divider grey over a transparent track, keeping the striped motif. */
  .Separator {
    background-color: transparent !important;
    background-image: repeating-linear-gradient(-45deg, #2d333b, #2d333b 6px, rgba(0, 0, 0, 0) 0, rgba(0, 0, 0, 0) 12px) !important;
  }

  /* Defaults to a #f0f0f0 disc with a black chevron. */
  .PageTopButton, .PageTopButtonContainer-pageTopButton {
    background-color: #1c2128 !important;
  }
  .PageTopButton svg, .PageTopButton path,
  .PageTopButtonContainer-pageTopButton svg,
  .PageTopButtonContainer-pageTopButton path { fill: #c4cdd6 !important; }

  /* Keep media untinted; just give empty thumb wells a dark fill */
  .Thumbnail-image, .NC-Thumbnail-image, .UserIcon-image,
  [class*="Thumbnail-image"] { background-color: #262c33 !important; }
  img, video, canvas { background-color: transparent !important; }

  /* Selection */
  ::selection { background-color: #2f6fb8 !important; color: #ffffff !important; }
}

@-moz-document url-prefix("https://www.nicovideo.jp/region_restriction") {
body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }
  h1 svg path { fill: #e6edf3 !important; }
  h2 { color: #e6edf3 !important; }
  a { color: #5fb0e6 !important; }
}
